examples.code:
aws cloudformation detect-stack-drift --stack-name app-network-stack

# after it completes:
aws cloudformation describe-stack-resource-drifts \
  --stack-name app-network-stack \
  --query "StackResourceDrifts[?StackResourceDriftStatus=='MODIFIED']"

# example result (abbreviated)
[
  {
    "LogicalResourceId": "AppSecurityGroup",
    "StackResourceDriftStatus": "MODIFIED",
    "PropertyDifferences": [
      { "PropertyPath": "/SecurityGroupIngress/1/CidrIp", "ExpectedValue": "10.0.0.0/16", "ActualValue": "0.0.0.0/0" }
    ]
  }
]

// dev-parameters.json
{ "EnvironmentName": "dev", "InstanceType": "t3.micro", "MinCapacity": 1, "MaxCapacity": 1 }

// prod-parameters.json
{ "EnvironmentName": "prod", "InstanceType": "m6g.large", "MinCapacity": 2, "MaxCapacity": 6 }

